files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0e0;
  --accent: #ff6b6b;
  --accent-hover: #ff8e8e;
  --accent-pressed: #e05555;
  --bar-bg: #3a3a55;
  --hunger-color: #f4a261;
  --happiness-color: #e9c46a;
  --energy-color: #2a9d8f;
  --focus-ring: #ffd166;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  color: #fff;
}

.pet-stage {
  display: flex;
  justify-content: center;
  margin-bottom: 1rem;
}

.pet {
  width: 120px;
  height: 120px;
  position: relative;
}

.pet-body {
  width: 100%;
  height: 100%;
  background: var(--accent);
  border-radius: 50% 50% 40% 40%;
  position: relative;
  box-shadow: inset -8px -8px 0 rgba(0, 0, 0, 0.15);
}

.pet-eye {
  width: 16px;
  height: 16px;
  background: #1e1e2f;
  border-radius: 50%;
  position: absolute;
  top: 40%;
}

.pet-eye.left { left: 28%; }
.pet-eye.right { right: 28%; }

.pet-mouth {
  width: 24px;
  height: 12px;
  border-bottom: 4px solid #1e1e2f;
  border-radius: 0 0 50% 50%;
  position: absolute;
  bottom: 30%;
  left: 50%;
  transform: translateX(-50%);
}

.mood {
  font-size: 1.125rem;
  margin-bottom: 1.5rem;
  min-height: 1.5em;
  font-weight: 600;
  color: #fff;
}

.bars {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.bar-group {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.bar-label {
  width: 90px;
  text-align: left;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text);
}

.bar-track {
  flex: 1;
  height: 16px;
  background: var(--bar-bg);
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 50%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar-fill.hunger { background: var(--hunger-color); }
.bar-fill.happiness { background: var(--happiness-color); }
.bar-fill.energy { background: var(--energy-color); }

.controls {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 0;
  min-width: 80px;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  color: #fff;
  background: var(--accent);
  transition: background 0.2s, transform 0.1s;
}

.btn:hover { background: var(--accent-hover); }
.btn:focus-visible { outline: 3px solid var(--focus-ring); outline-offset: 2px; }
.btn:active { background: var(--accent-pressed); transform: scale(0.97); }

.btn.feed { background: var(--hunger-color); }
.btn.feed:hover { background: #f4b87a; }
.btn.feed:active { background: #d98c4a; }

.btn.play { background: var(--happiness-color); color: #1e1e2f; }
.btn.play:hover { background: #f0d48a; }
.btn.play:active { background: #d4b05a; }

.btn.sleep { background: var(--energy-color); }
.btn.sleep:hover { background: #3ab8a8; }
.btn.sleep:active { background: #1f8a7e; }

@media (max-width: 360px) {
  .card { padding: 1.5rem 1rem; }
  .bar-label { width: 70px; font-size: 0.8rem; }
  .btn { font-size: 0.9rem; padding: 0.6rem 0.5rem; }
}

const state = {
  hunger: 50,
  happiness: 50,
  energy: 50
};

const moodEl = document.getElementById('mood-text');
const hungerFill = document.getElementById('hunger-fill');
const happinessFill = document.getElementById('happiness-fill');
const energyFill = document.getElementById('energy-fill');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateMood() {
  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood;
  if (avg >= 70) mood = 'Your pet is thrilled!';
  else if (avg >= 40) mood = 'Your pet is content.';
  else if (avg >= 20) mood = 'Your pet needs attention.';
  else mood = 'Your pet is very unhappy.';
  moodEl.textContent = mood;
}

function updateBars() {
  hungerFill.style.width = state.hunger + '%';
  happinessFill.style.width = state.happiness + '%';
  energyFill.style.width = state.energy + '%';
  hungerBar.setAttribute('aria-valuenow', state.hunger);
  happinessBar.setAttribute('aria-valuenow', state.happiness);
  energyBar.setAttribute('aria-valuenow', state.energy);
  updateMood();
}

function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.energy = clamp(state.energy - 5);
  updateBars();
}

function play() {
  state.happiness = clamp(state.happiness + 15);
  state.energy = clamp(state.energy - 10);
  state.hunger = clamp(state.hunger - 5);
  updateBars();
}

function sleep() {
  state.energy = clamp(state.energy + 20);
  state.hunger = clamp(state.hunger - 5);
  updateBars();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateBars();
